#!/usr/bin/env python3
"""Characterize next marker gap without implementing it or executing programs."""
import argparse,pathlib,subprocess,json,hashlib
p=argparse.ArgumentParser();p.add_argument('--hbpp',required=True);p.add_argument('--hpp',required=True);p.add_argument('--output-dir',required=True);a=p.parse_args();out=pathlib.Path(a.output_dir).resolve();out.mkdir(parents=True,exist_ok=True);rows=[]
for family,restriction,values,matches in [('inherit','FROM, INHERIT',['FROM','INHERIT','from','FR','FRO','FROMAGE','OTHER','FROM INHERIT','','INHE','INHER','"FROM"','(FROM)'],{'FROM','INHERIT','from'}),('descending','DESCENDING',['DESCENDING','descending','DESC','DESCENDIN','DESCENDINGLY','OTHER','','"DESCENDING"'],{'DESCENDING','descending'})]:
 for val in values:
  f=out/f'p{len(rows):02}.prg';text=f'#xcommand PROBE <mode: {restriction}> <!name!> => OUT( <mode>, <name> )\nPROBE {val} alpha\n';f.write_text(text);ref=subprocess.run([str(pathlib.Path(a.hbpp).resolve()),str(f),'-q2'],capture_output=True,text=True,timeout=10);assert ref.returncode==0,(val,ref.stderr);s=f.with_suffix('.ppo').read_text();matched='OUT('in s;assert matched==(val in matches),(val,s);own=subprocess.run([str(pathlib.Path(a.hpp).resolve()),str(f)],capture_output=True,text=True,timeout=10);assert own.returncode==1 and 'bad match marker'in own.stderr,(val,own.stderr);rows.append({'restriction':restriction,'input':val,'source_sha256':hashlib.sha256(text.encode()).hexdigest(),'reference_rule_matched':matched,'reference_preprocessed':s,'own_rejected_definition':True})
j={'reference':'harbour/core694428e1c12f726675b19324d62167fa77d68185','own_compiler':'e71b0ed961b59cb7c9d708eed942174bb6e386c4','scope':'21 own-source preprocessor-only next-gap probes. No implementation,compilation/linking/program execution. Not full restricted-marker grammar or permission to implement. Nonmatches leave reference source unchanged.','rows':rows};(out/'results.json').write_text(json.dumps(j,indent=2)+'\n');print(f'{len(rows)} reference restricted-marker observations;own rejection unchanged')
